package org.btcai.wallet;
import android.app.*;import android.os.*;import android.graphics.Color;import android.view.*;import android.widget.*;import android.text.InputType;import android.util.Base64;import org.json.*;import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;
public class MainActivity extends Activity {
 String[] langs={"English","فارسی","中文","Русский","Español","العربية","Deutsch","Français","Türkçe","हिन्दी"};
 String[][] words={{"Balance","Send","Receive","History","Connect","RPC user","RPC password","Address","Amount","Confirm","Cancel"},{"موجودی","ارسال","دریافت","تاریخچه","اتصال","نام کاربری RPC","رمز RPC","آدرس","مقدار","تأیید","لغو"},{"余额","发送","接收","历史","连接","RPC 用户","RPC 密码","地址","金额","确认","取消"},{"Баланс","Отправить","Получить","История","Подключить","RPC пользователь","RPC пароль","Адрес","Сумма","Подтвердить","Отмена"},{"Saldo","Enviar","Recibir","Historial","Conectar","Usuario RPC","Contraseña RPC","Dirección","Cantidad","Confirmar","Cancelar"},{"الرصيد","إرسال","استلام","السجل","اتصال","مستخدم RPC","كلمة مرور RPC","العنوان","المبلغ","تأكيد","إلغاء"},{"Guthaben","Senden","Empfangen","Verlauf","Verbinden","RPC Benutzer","RPC Passwort","Adresse","Betrag","Bestätigen","Abbrechen"},{"Solde","Envoyer","Recevoir","Historique","Connexion","Utilisateur RPC","Mot de passe RPC","Adresse","Montant","Confirmer","Annuler"},{"Bakiye","Gönder","Al","Geçmiş","Bağlan","RPC kullanıcı","RPC parola","Adres","Miktar","Onayla","İptal"},{"शेष","भेजें","प्राप्त करें","इतिहास","कनेक्ट","RPC उपयोगकर्ता","RPC पासवर्ड","पता","राशि","पुष्टि","रद्द"}};
 int l=0; String user="",pass=""; LinearLayout panel; TextView result; boolean busy=false; String t(int i){return words[l][i];}
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setFlags(8192,8192);l=getPreferences(0).getInt("lang",0);draw();}
 void draw(){ScrollView s=new ScrollView(this);panel=new LinearLayout(this);panel.setOrientation(1);panel.setPadding(32,40,32,32);panel.setBackgroundColor(0xff151515);panel.setLayoutDirection(l==1||l==5?View.LAYOUT_DIRECTION_RTL:View.LAYOUT_DIRECTION_LTR);s.addView(panel);setContentView(s);TextView title=new TextView(this);title.setText("BTCAi Wallet");title.setTextSize(30);title.setTextColor(0xffffcc55);panel.addView(title);Spinner sp=new Spinner(this);sp.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,langs));sp.setSelection(l);panel.addView(sp);sp.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){} public void onItemSelected(AdapterView<?> p,View v,int i,long id){if(i!=l){l=i;getPreferences(0).edit().putInt("lang",l).apply();draw();}}});button(t(4),()->connect());button(t(0),()->rpc("getbalances",new JSONArray()));button(t(1),()->send());button(t(2),()->rpc("getnewaddress",new JSONArray()));button(t(3),()->rpc("listtransactions",new JSONArray().put("*").put(20)));result=new TextView(this);result.setTextSize(17);result.setTextIsSelectable(true);result.setTextColor(Color.WHITE);panel.addView(result);}
 void button(String text,Runnable r){Button b=new Button(this);b.setText(text);b.setTextColor(0xff111111);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xffffcc55));panel.addView(b);b.setOnClickListener(v->r.run());}
 EditText field(LinearLayout p,String hint,int type){EditText e=new EditText(this);e.setHint(hint);e.setInputType(type);p.addView(e);return e;}
 LinearLayout form(){LinearLayout p=new LinearLayout(this);p.setOrientation(1);p.setPadding(24,12,24,12);return p;}
 void connect(){LinearLayout p=form();EditText u=field(p,t(5),1),pw=field(p,t(6),129);new AlertDialog.Builder(this).setTitle(t(4)).setView(p).setNegativeButton(t(10),null).setPositiveButton(t(9),(d,w)->{user=u.getText().toString();pass=pw.getText().toString();rpc("getbalances",new JSONArray());}).show();}
 void send(){LinearLayout p=form();EditText a=field(p,t(7),1),n=field(p,t(8),8194);new AlertDialog.Builder(this).setTitle(t(1)).setView(p).setNegativeButton(t(10),null).setPositiveButton(t(9),(d,w)->{try{String addr=a.getText().toString().trim();java.math.BigDecimal amount=new java.math.BigDecimal(n.getText().toString());if(addr.isEmpty()||amount.signum()<=0||amount.scale()>8)throw new Exception();new AlertDialog.Builder(this).setTitle(t(9)).setMessage(amount.toPlainString()+" BTCAi\n"+addr).setNegativeButton(t(10),null).setPositiveButton(t(9),(x,y)->rpc("sendtoaddress",new JSONArray().put(addr).put(amount))).show();}catch(Exception e){result.setText("Invalid address or amount");}}).show();}
 void rpc(String method,JSONArray params){if(busy)return;if(user.isEmpty()){connect();return;}busy=true;final String auth=user+":"+pass;new Thread(()->{String out;HttpURLConnection c=null;try{c=(HttpURLConnection)new URL("http://127.0.0.1:19337/wallet/BTCAi").openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(5000);c.setReadTimeout(20000);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Authorization","Basic "+Base64.encodeToString(auth.getBytes(StandardCharsets.UTF_8),Base64.NO_WRAP));c.setRequestProperty("Content-Type","application/json");JSONObject q=new JSONObject().put("jsonrpc","1.0").put("id","wallet").put("method",method).put("params",params);try(OutputStream os=c.getOutputStream()){os.write(q.toString().getBytes(StandardCharsets.UTF_8));}InputStream in=c.getResponseCode()<400?c.getInputStream():c.getErrorStream();ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] buf=new byte[4096];int k;while((k=in.read(buf))!=-1)b.write(buf,0,k);in.close();JSONObject j=new JSONObject(b.toString("UTF-8"));if(!j.isNull("error"))out=j.getJSONObject("error").optString("message");else{Object r=j.get("result");out=r instanceof JSONObject?((JSONObject)r).toString(2):r instanceof JSONArray?((JSONArray)r).toString(2):String.valueOf(r);}}catch(Exception e){out="RPC error: "+e.getMessage();}finally{if(c!=null)c.disconnect();}final String msg=out;runOnUiThread(()->{busy=false;result.setText(msg);});}).start();}
}
